'use client';

import { useActionState } from 'react';

type FormState = {
  success?: boolean;
  message?: string;
  errors?: {
    name?: string;
    email?: string;
    message?: string;
  };
};

async function submitContactForm(
  prevState: FormState,
  formData: FormData
): Promise<FormState> {
  'use server';

  const name = formData.get('name');
  const email = formData.get('email');
  const message = formData.get('message');

  const errors: FormState['errors'] = {};

  // Validate all fields are provided
  if (!name || typeof name !== 'string' || name.trim() === '') {
    errors.name = 'Name is required';
  }

  if (!email || typeof email !== 'string' || email.trim() === '') {
    errors.email = 'Email is required';
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    errors.email = 'Please provide a valid email address';
  }

  if (!message || typeof message !== 'string' || message.trim() === '') {
    errors.message = 'Message is required';
  }

  // If there are validation errors, return them
  if (Object.keys(errors).length > 0) {
    return { success: false, errors };
  }

  // Process the contact form submission
  // In a real application, you would save to a database or send an email
  console.log('Contact form submitted:', { name, email, message });

  return {
    success: true,
    message: 'Thank you for your message! We will get back to you soon.',
  };
}

export default function ContactForm() {
  const [state, formAction, isPending] = useActionState<FormState, FormData>(
    submitContactForm,
    {}
  );

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px' }}>
      <h2>Contact Us</h2>

      {state.success && (
        <div
          style={{
            padding: '10px',
            marginBottom: '20px',
            backgroundColor: '#d4edda',
            color: '#155724',
            borderRadius: '4px',
          }}
        >
          {state.message}
        </div>
      )}

      <form action={formAction}>
        <div style={{ marginBottom: '15px' }}>
          <label
            htmlFor="name"
            style={{ display: 'block', marginBottom: '5px' }}
          >
            Name:
          </label>
          <input
            type="text"
            id="name"
            name="name"
            style={{
              width: '100%',
              padding: '8px',
              border: state.errors?.name ? '1px solid red' : '1px solid #ccc',
              borderRadius: '4px',
            }}
            disabled={isPending}
          />
          {state.errors?.name && (
            <span style={{ color: 'red', fontSize: '14px' }}>
              {state.errors.name}
            </span>
          )}
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label
            htmlFor="email"
            style={{ display: 'block', marginBottom: '5px' }}
          >
            Email:
          </label>
          <input
            type="email"
            id="email"
            name="email"
            style={{
              width: '100%',
              padding: '8px',
              border: state.errors?.email ? '1px solid red' : '1px solid #ccc',
              borderRadius: '4px',
            }}
            disabled={isPending}
          />
          {state.errors?.email && (
            <span style={{ color: 'red', fontSize: '14px' }}>
              {state.errors.email}
            </span>
          )}
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label
            htmlFor="message"
            style={{ display: 'block', marginBottom: '5px' }}
          >
            Message:
          </label>
          <textarea
            id="message"
            name="message"
            rows={5}
            style={{
              width: '100%',
              padding: '8px',
              border: state.errors?.message
                ? '1px solid red'
                : '1px solid #ccc',
              borderRadius: '4px',
            }}
            disabled={isPending}
          />
          {state.errors?.message && (
            <span style={{ color: 'red', fontSize: '14px' }}>
              {state.errors.message}
            </span>
          )}
        </div>

        <button
          type="submit"
          disabled={isPending}
          style={{
            padding: '10px 20px',
            backgroundColor: isPending ? '#ccc' : '#007bff',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: isPending ? 'not-allowed' : 'pointer',
          }}
        >
          {isPending ? 'Sending...' : 'Send Message'}
        </button>
      </form>
    </div>
  );
}

